@push('scripts')<script>
if(location.hash==='#nueva-venta')document.getElementById('nueva-venta').open=true;const lines=document.getElementById('sale-lines');if(lines){let next={{ count(old('items',[[]])) }};const total=()=>{let sum=0;lines.querySelectorAll('.sale-line').forEach(row=>{const s=row.querySelector('select');sum+=Number(s.selectedOptions[0]?.dataset.price||0)*Number(row.querySelector('input').value||0)});document.getElementById('sale-total').textContent='Total: '+new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(sum/100)};lines.addEventListener('input',total);lines.addEventListener('click',e=>{if(e.target.closest('.remove-line')&&lines.children.length>1){e.target.closest('.sale-line').remove();total()}});document.getElementById('add-line').addEventListener('click',()=>{if(lines.children.length>=30)return;const row=lines.firstElementChild.cloneNode(true);row.querySelector('select').name='items['+next+'][product_id]';row.querySelector('select').value='';row.querySelector('input').name='items['+next+'][quantity]';row.querySelector('input').value=1;next++;lines.append(row);total()});total();}
</script>@endpush
